import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan - FR 3.5.5","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-5-create-media-campaign/plan.md","filePath":"feature/media-package-campaign/3-5-5-create-media-campaign/plan.md"}'),o={name:"feature/media-package-campaign/3-5-5-create-media-campaign/plan.md"};function p(r,e,s,l,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-fr-3-5-5" tabindex="-1">Plan - FR 3.5.5 <a class="header-anchor" href="#plan-fr-3-5-5" aria-label="Permalink to &quot;Plan - FR 3.5.5&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Implement E50-06 creation of a draft campaign from an approved workspace package.</p><p>Updated 2026-10-08: phase 1 confirms total quantities and two new Task types. Implement against <a href="./../phase-1-design/plan.html">phase-1 data/API contract</a>.</p><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><p>Stage 2 implementation: keep the legacy route as an adapter, add workspace-scoped create/detail/PATCH, serialize writes with the existing agreement row lock and add database uniqueness. PATCH carries a complete editable plan plus expectedVersion; empty optional fields clear content. Work-item list may be empty in DRAFT, but each supplied item is complete. Deliverable quantities are frozen from the approved snapshot, not editable Campaign allocations. Legacy RETAINER without explicit TOTAL is read-only pending BA conversion; do not alter its approved snapshot. PostgreSQL and Mongo runtime migrations are not automatically executed on developer data. Web uses a dedicated campaign feature inside the approved-package panel, replacing the prototype allocator; paired <code>src/i18n/locales/{vi,en}/campaign.json</code> keys.</p><ol><li>Audit duplicate campaigns per agreement and per Workspace. Keep the existing UNIQUE Workspace agreement relation. Add a unique campaign agreement FK, <code>work_items JSONB NOT NULL DEFAULT &#39;[]&#39;</code> and <code>content_version INT NOT NULL DEFAULT 1</code> migration plus equivalent V2 init schema update. Do not delete duplicate history.</li><li>Validate each item has stable ID, task type, name, and due date.</li><li>Validate approved package, workspace access, and campaign payload.</li><li>Create/read/update <code>DRAFT</code> plans with a version guard; enforce one Campaign per Workspace, including concurrent requests and COMPLETED campaigns. Do not permit agreement reassignment to bypass the limit. Keep the existing draft API compatible.</li><li>Replace cross-Campaign allocation behavior with total quantities for one Campaign; no monthly allowance. Preserve legacy columns/snapshots pending explicit conversion. Owner Workspace duplication is a separate delivery task.</li><li>Add Campaign list/detail/editor in Web, paired vi/en keys and light/dark/responsive states; show the existing Campaign instead of a create action once it exists.</li></ol>',7)])])}const h=a(o,[["render",p]]);export{g as __pageData,h as default};
